mapper.select:
SELECT id, title, industry, period_start AS periodStart, period_end AS periodEnd, summary, content, generated_at AS generatedAt, created_at AS createdAt FROM industry_reports
AND industry = #{industry}
ORDER BY generated_at DESC

SELECT st.id, st.report_id AS reportId, st.period, st.avg_salary AS avgSalary, st.job_count AS jobCount FROM salary_trends st JOIN industry_reports ir ON st.report_id = ir.id
AND ir.industry = #{industry}
ORDER BY st.period
